if 'These melting and crystallization simulations' not in s:
 s=s.replace('      <div class="intro-resources">', '      <p class="hero-contribution">These melting and crystallization simulations support both forward and inverse modeling, depending on the research objective.</p>\n      <div class="intro-resources">')
s=s.replace('<p>if <math', '<p class="equation-condition">if <math').replace('<p>The bulk partition coefficients', '<p class="partition-intro">The bulk partition coefficients')
s=s.replace('parameterizations of Beattie (1993) and Matzen et al. (2017).', 'parameterizations of <a href="https://link.springer.com/article/10.1007/bf00712982">Beattie (1993)</a> and <a href="https://link.springer.com/article/10.1007/s00410-016-1319-8">Matzen et al. (2017)</a>.')
